// Talents-Einladung (öffentlich) und Meta-App-Formular: Anfrage lesen (Stefan 18.10.2026).
// seite = Einladungsseite, start = Knopf "Mit ... verbinden", rueckkehr = Meta leitet zurück, meta_app = Formular Superadmin.
// Neu (Stefan 18.10.2026): rueckkehr_ig = Rückleitung der Instagram-Anmeldung (zweite Meta-App), auswahl_seite / auswahl_senden =
// Account-Auswahl nach der Anmeldung über Facebook (Auswahl-Code a, 48 Hex-Zeichen; gewählte Accounts konto, mehrfach).
// Alle Adressparameter per Regex prüfen; Fehler von Meta nur als feste Codes, nie error_description aus dem Link.
// Den Sitzungs-Cookie nur beim Meta-App-Formular lesen (Einladungsseiten sind ohne Ally-Konto).
// Der App-Geheimcode aus dem Formular geht nicht in diese Ausgabe; "Datenbank" liest ihn direkt aus dem Webhook.
const h = $json.headers || {}, q = $json.query || {}, b = $json.body || {};
const s = v => (typeof v === 'string' || typeof v === 'number') ? String(v).trim() : '';
const nur = (v, re) => re.test(s(v)) ? s(v) : '';
// Hinweise auf der Einladungsseite (e) und Zusatzhinweise (h, mit "-" verbunden), nur bekannte Codes
const E_CODES = ['ok', 'abgebrochen', 'fehler', 'zeit', 'kanal', 'nicht_bereit', 'zu_viele', 'technik', 'keine_seite', 'kein_konto', 'zuordnung', 'abgelaufen', 'ungueltig', 'doppelt']; // doppelt: Account schon bei einem anderen Talent (Stefan 18.10.2026)
// Weitere Plattformen (Stefan 18.10.2026, Vertrag Migration 48): kein_kanal = Google-Konto ohne YouTube-Kanal, kein_dauerzugang = kein Refresh-Token
E_CODES.push('kein_kanal', 'kein_dauerzugang');
// doppelt = einzelne Accounts schon bei einem anderen Talent, konten = mehrere Accounts verbunden (Stefan 18.10.2026)
const H_CODES = ['mehrere', 'rechte', 'doppelt', 'konten'];
// aufgabe = Facebook-Seiten ohne Aufgabe "Statistiken ansehen" nicht verbunden, privat = Pinterest-Konto ohne Unternehmenskonto (Stefan 18.10.2026)
H_CODES.push('aufgabe', 'privat');
// Hinweise auf der Auswahlseite nach dem Absenden (Stefan 18.10.2026)
const AUSWAHL_E = ['leer', 'auswahl'];
// Kennzeichen für die Auswahlseite (Stefan 18.10.2026): rechte = nicht alle Berechtigungen erteilt, seiten = Meta meldet mehr als 100 Facebook-Seiten
const AUSWAHL_H = ['rechte', 'seiten'];
// aufgabe = Facebook-Seiten ohne "Statistiken ansehen" nicht angeboten; geht über die Auswahl mit auf die Einladungsseite (Stefan 18.10.2026)
AUSWAHL_H.push('aufgabe');
const kennz = v => s(v).split('-').filter(x => AUSWAHL_H.includes(x)).filter((x, i, a) => a.indexOf(x) === i).join('-');
const KONTO_ID = /^[A-Za-z0-9_.:-]{1,100}$/;
let art = 'meta_app';
if ($('Einladung').isExecuted) art = 'seite';
else if ($('Verbinden').isExecuted) art = 'start';
else if ($('Rückkehr').isExecuted) art = 'rueckkehr';
else if ($('Rückkehr Instagram').isExecuted) art = 'rueckkehr_ig';
else if ($('Auswahl').isExecuted) art = 'auswahl_seite';
else if ($('Auswahl senden').isExecuted) art = 'auswahl_senden';
// Rückkehr der weiteren Plattformen (Stefan 18.10.2026, Vertrag Migration 48): die Plattform kommt aus dem Webhook, nicht aus der Adresse
const WEITERE = { 'Rückkehr Facebook': 'facebook', 'Rückkehr Threads': 'threads', 'Rückkehr Google': 'youtube', 'Rückkehr Pinterest': 'pinterest', 'Rückkehr TikTok': 'tiktok' };
let weiterePl = '';
if (art === 'meta_app') for (const [knoten, pl] of Object.entries(WEITERE)) if ($(knoten).isExecuted) { art = 'rueckkehr_weitere'; weiterePl = pl; }
const o = { art, t: '', e: '', h: '', p: '', w: '', state: '', code: '', meta_fehler: '', token: '', herkunft: '', app_id: '', a: '', konten: [], abbrechen: false, zurueck: false };
if (art === 'rueckkehr_weitere') o.p = weiterePl;
if (art === 'seite' || art === 'start') {
  o.t = nur(q.t, /^[0-9a-fA-F]{64}$/).toLowerCase();
  o.p = nur(q.p, /^[a-z]{1,20}$/);
  o.w = nur(q.w, /^[a-z]{1,20}$/);
  if (art === 'seite') {
    o.e = E_CODES.includes(s(q.e)) ? s(q.e) : '';
    o.h = s(q.h).split('-').filter(x => H_CODES.includes(x)).filter((x, i, a) => a.indexOf(x) === i).join('-');
  }
} else if (art === 'rueckkehr' || art === 'rueckkehr_ig' || art === 'rueckkehr_weitere') {
  o.state = nur(q.state, /^[0-9a-fA-F]{48}$/).toLowerCase();
  o.code = nur(q.code, /^[\x21-\x7e]{1,2000}$/);
  // Instagram hängt an den Code "#_" an; das gehört nicht zum Code (laut Meta-Doku entfernen) (Stefan 18.10.2026)
  if (art === 'rueckkehr_ig') o.code = o.code.replace(/#_$/, '');
  // Threads hängt ebenfalls "#_" an; TikTok-Code kommt von n8n bereits dekodiert; Pinterest: jedes error gilt als Abbruch bzw. Ablehnung (Stefan 18.10.2026)
  if (art === 'rueckkehr_weitere' && o.p === 'threads') o.code = o.code.replace(/#_$/, '');
  const fe = s(q.error);
  if (fe) o.meta_fehler = fe === 'access_denied' ? 'abgebrochen' : 'abgelehnt';
} else if (art === 'auswahl_seite') {
  // Auswahlseite (Stefan 18.10.2026): nur der Auswahl-Code; Hinweis nach dem Absenden (leer, auswahl)
  o.a = nur(q.a, /^[0-9a-fA-F]{48}$/).toLowerCase();
  o.e = AUSWAHL_E.includes(s(q.e)) ? s(q.e) : '';
  o.h = kennz(q.h);
} else if (art === 'auswahl_senden') {
  // Formular der Auswahlseite (Stefan 18.10.2026): a, konto (mehrfach), abbrechen bzw. zurueck (von der Seite "Zeit abgelaufen").
  // Die Datenbank prüft Code, Ablauf und ob die Accounts zur Auswahl gehören.
  o.a = nur(b.a, /^[0-9a-fA-F]{48}$/).toLowerCase();
  // Kennzeichen aus dem versteckten Feld h (nur feste Codes, keine Schlüssel)
  o.h = kennz(b.h);
  const roh = Array.isArray(b.konto) ? b.konto : (b.konto && typeof b.konto === 'object' ? Object.values(b.konto) : (b.konto === undefined ? [] : [b.konto]));
  o.konten = roh.map(s).filter(x => KONTO_ID.test(x)).filter((x, i, a) => a.indexOf(x) === i).slice(0, 50);
  o.zurueck = s(b.zurueck) !== '';
  o.abbrechen = s(b.abbrechen) !== '' || o.zurueck;
} else {
  // Herkunft und Sitzung wie bei ALLY 15: Origin = eigene Adresse, oder Origin leer/"null" und Verweis genau von der Seite
  const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(h.host || '').trim().toLowerCase());
  const herkunft = String(h.origin || ''), verweis = String(h.referer || '');
  const SEITE_PFAD = HOST + '/webhook/web';
  const vonSeite = HOST !== '' && verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
  const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
  const kekse = String(h.cookie || '').split(';').map(x => x.trim());
  const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
  o.token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
  o.herkunft = herkunftOk ? 'ok' : 'ungueltig';
  // App-ID ist keine geheime Angabe; Prüfung des Formats in meta_app_web_aktion
  o.app_id = s(b.app_id).slice(0, 40);
}
return [{ json: o }];

// Öffentliche Einladungsseite für Talents (Stefan 18.10.2026): ohne Ally-Konto, im Corporate Design der Agentur (CD 1).
// Daten aus einladung_daten(t): Firma, Produkt, Anbieter, Talent, Kanäle mit Status und Anmeldewegen. Kein Token und kein Schlüssel in den Daten.
// Hinweise kommen nur als feste Codes über die Adresse (e, p, h), Texte stehen hier. Stil wie "Seite bauen" in ALLY 8.
// Mehrere Accounts (Stefan 18.10.2026): je Plattform die verbundenen Accounts und je bereitem Anmeldeweg ein Knopf (Vertrag Migration 45, 3.1);
// außerdem die Auswahlseite "Welche Accounts gehören zu dieser Einladung?" (art auswahl_seite, Daten aus einladung_auswahl_lesen, 3.6).
const CD = $('Corporate Design (CD 1)').first().json;
const A = $('Anfrage lesen').first().json;
const D = $('Datenbank').first().json.r || {};
const EINL = '/webhook/web/einladung';
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const txt = v => String(v ?? '').trim();
const FIRMA = txt(D.firma), PN = txt(D.produkt_name), ANB = txt(D.anbieter_name);
const F1 = esc(FIRMA || 'Deine Agentur'), F2 = esc(FIRMA || 'deine Agentur');
const PNE = esc(PN || 'diese Anwendung'), ANBE = esc(ANB || 'der Anbieter');
const PLATTFORMEN = { instagram: 'Instagram', facebook: 'Facebook', threads: 'Threads', youtube: 'YouTube', tiktok: 'TikTok', pinterest: 'Pinterest' };
const kanaele = Array.isArray(D.kanaele) ? D.kanaele.filter(k => k && PLATTFORMEN[k.plattform]) : [];
const pName = p => { const k = kanaele.find(x => x.plattform === p); return txt((k && k.name) || PLATTFORMEN[p] || ''); };
const F = CD.farben, AB = CD.abgeleitet;
const logo = (CD.logos || {}).logo_fuer_dunkel;
const stil = `${CD.fontCss || ''}
:root { --dunkel:${F.dunkel}; --weiss:${F.textAufDunkel}; --akzent:${F.akzent}; --akzentDunkel:${F.akzentDunkel}; --hell:${F.hell}; --grau:${F.grau}; --warn:${F.warnung}; --linie:${AB.tabellenLinie}; --neben:${AB.dunkelNebentext}; }
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--hell); }
body { font-family: '${CD.schrift}', sans-serif; color: var(--dunkel); font-size: 15px; line-height: 1.5; min-height: 100vh; }
.leiste { background: var(--dunkel); color: var(--weiss); }
.leiste .innen { max-width: 760px; margin: 0 auto; height: 60px; padding: 0 16px; display: flex; align-items: center; gap: 12px; }
.leiste img { height: 22px; display: block; }
.leiste .name { font-weight: 800; font-size: 16px; }
.rahmen { max-width: 760px; margin: 0 auto; padding: 0 16px 48px; }
.seitenkopf { padding: 26px 0 18px; }
.seitenkopf h1 { margin: 0; font-size: 26px; font-weight: 800; }
.seitenkopf p { margin: 6px 0 0; color: var(--grau); font-size: 15px; }
.karte { background: #FFFFFF; border-radius: 12px; padding: 20px 18px; margin: 0 0 16px; box-shadow: 0 2px 10px rgba(23,29,35,.06); }
h2 { margin: 0 0 8px; font-size: 19px; font-weight: 800; }
p { margin: 0 0 10px; }
ul { margin: 0 0 10px; padding-left: 20px; }
li { margin: 3px 0; }
.klein { font-size: 13px; color: var(--grau); }
.hinweis { border-radius: 9px; padding: 12px 14px; font-size: 14.5px; margin: 0 0 16px; }
.hinweis.ok { background: #EEF4E6; border-left: 4px solid var(--akzentDunkel); }
.hinweis.fehler { background: #FBEFEC; border-left: 4px solid var(--warn); }
.hinweis p:last-child { margin-bottom: 0; }
.kanal { border-top: 1px solid var(--linie); padding: 16px 0; }
.kanal:first-of-type { border-top: 0; padding-top: 4px; }
.kanal .kopf { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.kanal h3 { margin: 0; font-size: 17px; font-weight: 800; }
.kanal .stand { color: var(--grau); font-size: 14px; margin: 4px 0 0; }
.kanal .erkl { font-size: 14px; margin: 10px 0 0; }
.marke { font-size: 12px; font-weight: 700; padding: 3px 9px; border-radius: 999px; background: var(--hell); color: var(--grau); white-space: nowrap; }
.marke.an { background: #EEF4E6; color: var(--akzentDunkel); }
.marke.aus { background: #FBEFEC; color: var(--warn); }
.knopf { display: inline-block; font: inherit; font-weight: 700; font-size: 15px; padding: 12px 18px; border: 0; border-radius: 9px; background: var(--akzentDunkel); color: #FFFFFF; text-decoration: none; margin-top: 12px; text-align: center; }
.knopf.zweit { background: #FFFFFF; color: var(--dunkel); border: 1.5px solid var(--linie); }
.knopf:focus-visible { outline: 2px solid var(--akzent); outline-offset: 2px; }
.vertretung { background: var(--hell); border-radius: 9px; padding: 12px 14px; font-size: 14px; margin-top: 6px; }
details.ds summary { cursor: pointer; font-weight: 800; font-size: 19px; list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 10px; }
details.ds summary::-webkit-details-marker { display: none; }
details.ds summary::after { content: '+'; font-size: 22px; color: var(--akzentDunkel); }
details.ds[open] summary::after { content: '–'; }
dl.ds-liste { margin: 14px 0 0; }
dl.ds-liste dt { font-weight: 700; font-size: 14px; margin-top: 12px; }
dl.ds-liste dd { margin: 2px 0 0; font-size: 14px; }
.platzhalter { color: var(--grau); font-style: italic; }
/* Accounts je Plattform, Anmeldewege, Auswahlseite (Stefan 18.10.2026) */
ul.konten { list-style: none; padding: 0; margin: 10px 0 0; }
ul.konten li { padding: 7px 0; border-top: 1px solid var(--linie); font-size: 14px; }
ul.konten li:first-child { border-top: 0; }
ul.konten .at { font-weight: 700; }
ul.konten .aus { color: var(--warn); }
.weg { margin-top: 12px; }
.weg .knopf { margin-top: 0; }
.weg .klein { margin: 6px 0 0; }
.weiterer { font-weight: 700; font-size: 14px; margin: 14px 0 0; }
label.konto { display: flex; gap: 12px; align-items: flex-start; padding: 12px 0; border-top: 1px solid var(--linie); cursor: pointer; }
label.konto:first-of-type { border-top: 0; }
label.konto input { width: 20px; height: 20px; margin: 2px 0 0; accent-color: var(--akzentDunkel); flex: none; }
label.konto .kname { font-weight: 700; display: block; }
label.konto .kat { color: var(--grau); font-size: 14px; }
label.konto .khinweis { display: block; font-size: 13px; color: var(--grau); margin-top: 2px; }
label.konto.belegt { cursor: default; opacity: .6; }
label.konto.belegt .khinweis { color: var(--warn); }
.knoepfe { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 6px; }
.fuss { text-align: center; padding: 8px 0 0; }
.fuss a { color: inherit; }
@media (max-width: 560px) {
  .seitenkopf h1 { font-size: 23px; }
  .knopf { display: block; width: 100%; }
}`;
const leiste = '<header class="leiste"><div class="innen">' + (logo ? '<img src="' + esc(logo) + '" alt="' + esc(FIRMA) + '">' : '<span class="name">' + esc(FIRMA || PN) + '</span>') + '</div></header>';
const huelle = (inhalt, titel) => '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">'
  + '<meta name="robots" content="noindex, nofollow"><meta name="referrer" content="no-referrer"><title>' + esc(titel) + '</title><style>' + stil + '</style></head><body>'
  + leiste + '<main class="rahmen">' + inhalt + '</main></body></html>';
const kopf = (titel, unter) => '<div class="seitenkopf"><h1>' + esc(titel) + '</h1>' + (unter ? '<p>' + unter + '</p>' : '') + '</div>';
const box = (html, art) => '<div class="hinweis ' + (art === 'ok' ? 'ok' : 'fehler') + '" role="' + (art === 'ok' ? 'status' : 'alert') + '">' + html + '</div>';
const titelVor = t => (FIRMA ? FIRMA + ' – ' : '') + t;

// Hinweise nach einer Anmeldung (Codes aus der Adresse)
const P = esc(pName(A.p) || 'den Kanal');
// Instagram direkt (ohne Facebook-Seite) möglich? Dann bei fehlender Seite darauf hinweisen (Stefan 18.10.2026)
const igDirekt = (() => { const k = kanaele.find(x => x.plattform === 'instagram'); return !!k && k.bereit === true && Array.isArray(k.wege)
  && k.wege.some(w => w && w.weg === 'instagram' && w.bereit === true); })();
const igDirektText = igDirekt ? ' Ohne Facebook-Seite kannst du stattdessen „Mit Instagram direkt verbinden“ nutzen.' : '';
const mehrereOk = String(A.h || '').split('-').includes('konten');
const MELD = {
  ok: ['<p><strong>' + (mehrereOk ? 'Die ausgewählten ' + P + '-Accounts sind verbunden.' : P + ' ist verbunden.') + '</strong> Danke! Du musst nichts weiter tun.</p>', 'ok'],
  abgebrochen: ['<p>Die Anmeldung wurde abgebrochen. Du kannst es jederzeit noch einmal versuchen.</p>', 'fehler'],
  fehler: ['<p>Die Verbindung hat nicht geklappt. Bitte noch einmal versuchen. Wenn es wieder nicht klappt, gib bitte ' + F2 + ' Bescheid.</p>', 'fehler'],
  zeit: ['<p>Die Anmeldung hat zu lange gedauert. Bitte noch einmal auf den Knopf tippen.</p>', 'fehler'],
  kanal: ['<p>Dieser Kanal ist in deiner Einladung nicht vorgesehen.</p>', 'fehler'],
  nicht_bereit: ['<p>Die Anmeldung für ' + P + ' ist noch nicht eingerichtet. Bitte später noch einmal versuchen oder bei ' + F2 + ' nachfragen.</p>', 'fehler'],
  zu_viele: ['<p>Zu viele Anmeldeversuche. Bitte in 15 Minuten noch einmal versuchen.</p>', 'fehler'],
  technik: ['<p>Gerade gibt es ein technisches Problem. Bitte später noch einmal versuchen oder bei ' + F2 + ' nachfragen.</p>', 'fehler'],
  // Facebook-Seiten (Stefan 18.10.2026, Vertrag Migration 48): eigener Text, wenn die Plattform Facebook ist (sonst Instagram über Facebook)
  keine_seite: A.p === 'facebook' ? ['<p>Es wurde keine Facebook-Seite gefunden, deren Statistiken du ansehen darfst.</p>', 'fehler'] : ['<p>Es wurde keine Facebook-Seite gefunden. Über Facebook lässt sich Instagram nur mit einer Facebook-Seite verbinden, die mit deinem Instagram-Konto verknüpft ist. '
    + 'Bitte bei der Anmeldung die Seite auswählen und freigeben.' + esc(igDirektText) + '</p>', 'fehler'],
  kein_konto: ['<p>Keine der freigegebenen Facebook-Seiten ist mit einem Instagram-Business- oder Creator-Konto verknüpft. '
    + 'Bitte in der Instagram-App auf ein Business- oder Creator-Konto wechseln, es mit deiner Facebook-Seite verknüpfen und dann noch einmal verbinden.' + esc(igDirektText) + '</p>', 'fehler'],
  // YouTube, Pinterest, TikTok (Stefan 18.10.2026, Vertrag Migration 48)
  kein_kanal: ['<p>Zu diesem Google-Konto gibt es keinen YouTube-Kanal. Bitte mit dem Google-Konto anmelden, dem der Kanal gehört.</p>', 'fehler'],
  kein_dauerzugang: ['<p>Die Plattform hat keinen dauerhaften Zugang erteilt. Bitte noch einmal verbinden und alle Fragen bestätigen.</p>', 'fehler'],
  zuordnung: ['<p>Die Anmeldung konnte nicht zugeordnet werden. Bitte den Einladungslink aus der Nachricht noch einmal öffnen.</p>', 'fehler'],
  // Keine Doppelten (Stefan 18.10.2026): Account schon bei einem anderen Talent verbunden; Text aus einladung_daten (doppelt_meldung), sonst fest
  doppelt: ['<p>' + esc(txt((kanaele.find(x => x.plattform === A.p) || {}).doppelt_meldung) || 'Dieser ' + (pName(A.p) || 'Plattform') + '-Account ist bereits mit einem anderen Talent verbunden. Bitte die Agentur kontaktieren.') + '</p>', 'fehler']
};
const ZUSATZ = {
  mehrere: 'Es waren mehrere Instagram-Konten freigegeben. Verbunden ist das erste. Falls das nicht das richtige ist, bitte noch einmal verbinden und bei Facebook nur das gewünschte Konto auswählen.',
  rechte: 'Nicht alle Berechtigungen wurden erteilt. Damit alle Zahlen abgerufen werden können, bitte noch einmal verbinden und alle Berechtigungen bestätigen.',
  // Teilweise abgelehnt (Stefan 18.10.2026)
  doppelt: 'Mindestens ein Account ist bereits mit einem anderen Talent verbunden und wurde nicht verbunden. Bitte die Agentur kontaktieren.',
  // Weitere Plattformen (Stefan 18.10.2026, Vertrag Migration 48)
  aufgabe: 'Seiten ohne die Berechtigung „Statistiken ansehen“ wurden nicht verbunden.',
  privat: 'Pinterest liefert viele Zahlen nur für Unternehmenskonten.'
};
// Links zu den Rechtstexten (ALLY 17) in der Fußzeile, relativ (Stefan 18.10.2026, Vertrag Migration 50)
const RECHT = '<br><a href="/webhook/web/meta/datenschutz">Datenschutzhinweise</a> · <a href="/webhook/web/meta/datenloeschung">Datenlöschung</a>'
  + ' · <a href="/webhook/web/meta/nutzungsbedingungen">Nutzungsbedingungen</a>';

let html;
if (A.art === 'auswahl_seite') {
  // Auswahlseite (Stefan 18.10.2026): mehrere Instagram-Konten nach der Anmeldung über Facebook. Texte aus einladung_auswahl_lesen.
  const AUSW = EINL + '/auswahl';
  const code = /^[0-9a-f]{48}$/.test(String(A.a || '')) ? A.a : '';
  const pn = esc(txt(D.plattform_name) || pName(D.plattform) || 'Kanal');
  if (D.ok !== true) {
    // Abgelaufen, schon benutzt, Einladung ungültig oder technisches Problem: Meldung und Weg zurück
    const TITEL = { zeit: 'Zeit abgelaufen', ungueltig: 'Auswahl nicht mehr gültig', abgelaufen: 'Link abgelaufen', technik: 'Technisches Problem' };
    const t = TITEL[D.grund] || 'Auswahl nicht mehr gültig';
    const text = esc(txt(D.fehler) || 'Diese Auswahl ist nicht mehr gültig. Bitte den Einladungslink aus der Nachricht noch einmal öffnen.');
    // Nur bei "Zeit abgelaufen" kennt die Datenbank den Einladungslink noch: Knopf führt über das Formular zurück (Code wird dabei verbraucht)
    const zurueck = D.grund === 'zeit' && code
      ? '<form method="post" action="' + AUSW + '"><input type="hidden" name="a" value="' + code + '">'
