  // Code (POST, 1 Stunde gültig) -> kurzer Schlüssel + user_id -> th_exchange_token (60 Tage) -> /me?fields=id,username
  const K = lauf('TH Code tauschen'), L = lauf('TH langer Schlüssel'), P = lauf('TH Profil holen');
  const kb = flach(koerper(K)), lang = String(koerper(L).access_token || ''), pb = koerper(P);
  if (!K || st(K) !== 200 || !tok(kb.access_token)) { aktion = 'fehler'; fehler = 'Code-Tausch bei Threads fehlgeschlagen' + code(K) + '.'; }
  else if (!L || st(L) !== 200 || !tok(lang)) { aktion = 'fehler'; fehler = 'Langlebiger Schlüssel nicht erhalten' + code(L) + '.'; }
  else if (!P || st(P) !== 200 || !/^[0-9]{1,40}$/.test(String(pb.id || ''))) { aktion = 'fehler'; fehler = 'Threads-Profil nicht lesbar' + code(P) + '.'; }
  else {
    const bis = Number(koerper(L).expires_in) > 0 ? String(Math.floor(Number(koerper(L).expires_in))) : '';
    aktion = 'speichern'; e = 'ok';
    daten = JSON.stringify({ extern_id: String(pb.id), extern_name: String(pb.username || '').trim().replace(/^@/, '').slice(0, 100), schluessel: lang, gueltig_bis: bis, anmeldeweg: 'threads' });
  }
} else if (pl === 'youtube') {
  // Code -> access_token + refresh_token (nur mit access_type=offline; mit prompt=consent auch bei erneuter Anmeldung) -> channels?mine=true
  const K = lauf('GO Code tauschen'), C = lauf('GO Kanal holen');
  const kb = koerper(K), items = Array.isArray(koerper(C).items) ? koerper(C).items : [];
  const kanal = items.find(x => x && /^[A-Za-z0-9_-]{10,40}$/.test(String(x.id || '')));
  if (!K || st(K) !== 200 || !tok(kb.access_token)) { aktion = 'fehler'; fehler = 'Code-Tausch bei Google fehlgeschlagen' + code(K) + '.'; }
  else if (!tok(kb.refresh_token)) { aktion = 'fehler'; e = 'kein_dauerzugang'; fehler = 'Google hat keinen Dauerzugang (Refresh-Token) geliefert.'; }
  else if (!C || st(C) !== 200) { aktion = 'fehler'; fehler = 'YouTube-Kanal nicht lesbar' + code(C) + '.'; }
  else if (!kanal) { aktion = 'fehler'; e = 'kein_kanal'; fehler = 'Zu diesem Google-Konto gibt es keinen YouTube-Kanal.'; }
  else {
    const r = liste(kb.scope, /\s+/);
    pruefeRechte(r);
    const bis = Number(kb.refresh_token_expires_in) > 0 ? String(Math.floor(Number(kb.refresh_token_expires_in))) : '';
    const d = { extern_id: String(kanal.id), extern_name: String(((kanal.snippet || {}).title) || '').trim().slice(0, 100), schluessel: kb.refresh_token, gueltig_bis: bis, anmeldeweg: 'google' };
    if (r.length) d.berechtigungen = r;
    aktion = 'speichern'; e = 'ok'; daten = JSON.stringify(d);
  }
} else if (pl === 'pinterest') {
  // Code (POST mit HTTP Basic) -> access_token (30 Tage) + refresh_token (60 Tage, fortlaufend) -> /user_account
  const K = lauf('PI Code tauschen'), U = lauf('PI Konto holen');
  const kb = koerper(K), ub = koerper(U);
  if (!K || st(K) !== 200 || !tok(kb.access_token)) { aktion = 'fehler'; fehler = 'Code-Tausch bei Pinterest fehlgeschlagen' + code(K) + '.'; }
  else if (!tok(kb.refresh_token)) { aktion = 'fehler'; e = 'kein_dauerzugang'; fehler = 'Pinterest hat keinen Dauerzugang (Refresh-Token) geliefert.'; }
  else if (!U || st(U) !== 200 || !(ID.test(String(ub.id || '')) || /^[A-Za-z0-9_.-]{1,100}$/.test(String(ub.username || '')))) { aktion = 'fehler'; fehler = 'Pinterest-Konto nicht lesbar' + code(U) + '.'; }
  else {
    const r = liste(kb.scope);
    pruefeRechte(r);
    const bis = Number(kb.refresh_token_expires_in) > 0 ? String(Math.floor(Number(kb.refresh_token_expires_in))) : '';
    const d = { extern_id: String(ub.id || ub.username), extern_name: String(ub.username || '').trim().slice(0, 100), schluessel: kb.refresh_token, gueltig_bis: bis, anmeldeweg: 'pinterest' };
    if (r.length) d.berechtigungen = r;
    if (ub.account_type && ub.account_type !== 'BUSINESS') h.push('privat');
    aktion = 'speichern'; e = 'ok'; daten = JSON.stringify(d);
  }
} else if (pl === 'tiktok') {
  // Code (POST, client_key) -> open_id, access_token (24 h), refresh_token (365 Tage), scope -> /user/info/?fields=open_id,display_name
  const K = lauf('TT Code tauschen'), U = lauf('TT Konto holen');
  const kb = koerper(K), ub = (koerper(U).data || {}).user || {};
  if (!K || st(K) !== 200 || !tok(kb.access_token) || !ID.test(String(kb.open_id || ''))) { aktion = 'fehler'; fehler = 'Code-Tausch bei TikTok fehlgeschlagen' + code(K) + '.'; }
  else if (!tok(kb.refresh_token)) { aktion = 'fehler'; e = 'kein_dauerzugang'; fehler = 'TikTok hat keinen Dauerzugang (Refresh-Token) geliefert.'; }
  else {
    const r = liste(kb.scope, ',');
    pruefeRechte(r);
    const bis = Number(kb.refresh_expires_in) > 0 ? String(Math.floor(Number(kb.refresh_expires_in))) : '';
    const d = { extern_id: String(kb.open_id), extern_name: String(ub.display_name || '').trim().slice(0, 100), schluessel: kb.refresh_token, gueltig_bis: bis, anmeldeweg: 'tiktok' };
    if (r.length) d.berechtigungen = r;
    aktion = 'speichern'; e = 'ok'; daten = JSON.stringify(d);
  }
} else {
  e = 'technik';
}
if (aktion !== 'keine' && kanal_id === null) { aktion = 'keine'; e = 'technik'; }
const link_token = aktion === 'auswahl' && /^[0-9a-f]{64}$/.test(String(R.link_token || '')) ? R.link_token : '';
return [{ json: { aktion, kanal_id, e, h: h.join('-'), fehler: fehler.slice(0, 300), daten, link_token, plattform: /^[a-z]{1,20}$/.test(pl) ? pl : '' } }];

// Sofortabruf planen (Stefan 19.10.2026): nach der Weiterleitung (die Antwort an das Talent ist schon gesendet) für jeden gerade
// verbundenen bzw. erneuerten Account den passenden Abruf-Workflow starten ("Sofortabruf starten", ohne Warten), damit Talent und Manager
// sofort Zahlen sehen. Quelle: Rückgabe von einladung_kanal_speichern ("Kanal speichern") bzw. einladung_auswahl_abschliessen
// ("Datenbank" bei "Auswahl senden"), Feld gespeichert[].kanal_id. Keine Schlüssel. Fehler hier ändern nichts an der Verbindung;
// im Zweifel startet nichts, dann holt der nächtliche Lauf die Zahlen.
const WF = {"instagram": ["F3XM9bJAw7sfZaj3", "uZGf87ReGZtpjOGS"], "facebook": ["yhWZEzG6acRQ3u0C"], "threads": ["jIF2zFvSG4TJzKkv"], "youtube": ["rlOTAsqL1fNEQ8yS"], "pinterest": ["ONcCjiSJdLq2FBqF"], "tiktok": ["LLnW6tl2JAgCI8OO"]};
const lies = n => { try { return $(n).isExecuted ? ($(n).first().json || null) : null; } catch (e) { return null; } };
let x = null;
const ks = lies('Kanal speichern');
if (ks && ks.r && ks.r.ok === true) x = ks.r;
else {
  const a = lies('Anfrage lesen'), d = lies('Datenbank');
  if (a && a.art === 'auswahl_senden' && d && d.r && d.r.ok === true) x = d.r;
}
if (!x) return [];
const wfs = (WF[String(x.plattform || '')] || []).filter(w => /^[A-Za-z0-9]{16}$/.test(w));
const ids = [];
for (const g of (Array.isArray(x.gespeichert) ? x.gespeichert : [])) {
