}
const out = [];
// TALENTS 1 bzw. der Plattform-Abruf je Account; bei Instagram zusätzlich TALENTS 3 (Zielgruppe)
for (const id of ids.slice(0, 50)) for (const w of wfs) out.push({ json: { workflow_id: w, kanal_id: id, erstabruf: true } });
