// Rückweg wählen (ALLY 16, BA8, Stefan 20.10.2026): Ziel aus „Rückweg prüfen“, wenn es ein Pfad zum Talent-Bereich ist, sonst das bisherige Ziel
// (Einladungsseite bzw. Auswahlseite). Fehler der Datenbank ändern nichts: dann das bisherige Ziel.
const vorher = $('Rückkehr abschließen').isExecuted ? $('Rückkehr abschließen').first().json : $('Auswahl auswerten').first().json;
