// Logo bauen (ALLY 16, Plan 57, Migration 192; Entscheidung Stefan 01.11.2026 „Logo als Bild unter fester Adresse“): öffentliche Bildadresse nur für das Logo der
// Mails (Logo für dunkle Flächen der eigenen Firma, nur PNG; ally_cd_logo_mail). Kein Verzeichnis, keine anderen Dateien, keine Kennungen; der Parameter v dient nur
// zum Neuladen nach einem Wechsel und wird nicht ausgewertet. Ohne PNG-Logo (z. B. nur SVG) 404; die Mail zeigt dann den Firmennamen.
const l = ($input.first().json || {}).l || null;
const ok = !!(l && l.mime === 'image/png' && /^[A-Za-z0-9+/]+={0,2}$/.test(String(l.daten || '')) && String(l.daten).startsWith('iVBORw0KGgo'));
if (!ok) return [{ json: { da: false } }];
return [{ json: { da: true }, binary: { datei: { data: String(l.daten), mimeType: 'image/png', fileName: 'logo.png', fileExtension: 'png' } } }];
